-- 0009_verification.sql\nCREATE TABLE verification_events (id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE, peer_id TEXT NOT NULL REFERENCES pool_nodes(id) ON DELETE CASCADE, tier TEXT NOT NULL, outcome TEXT NOT NULL CHECK (outcome IN ('verified','pending','failed','corrected')), sampler TEXT NOT NULL, latency_ms INTEGER NOT NULL, created_at INTEGER NOT NULL);\n\n